-- Task 4.10c: the Finance step can be switched off (06-approval-workflow.md, Finance step switched
-- off; D62). Generated by drizzle-kit, then the trigger at the end added by hand. No statement of
-- this migration uses the new enum value, so ADD VALUE may run inside the migration's transaction.
-- `finance_step` gets its CHECK and no row: a missing key has its default, true (14 Notes for the
-- build).
ALTER TYPE "public"."order_action_type" ADD VALUE 'CLOSE_SKIPPED' BEFORE 'SEND_TO_SETTLEMENT';--> statement-breakpoint
ALTER TYPE "public"."order_event_type" ADD VALUE 'CLOSE_SKIPPED' BEFORE 'SEND_TO_SETTLEMENT';--> statement-breakpoint
ALTER TABLE "orders" ADD COLUMN "skipped_finance" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "orders" ADD CONSTRAINT "orders_skipped_finance_status_check" CHECK (NOT "orders"."skipped_finance" OR "orders"."status" NOT IN ('PENDING_FINANCE', 'SETTLEMENT'));--> statement-breakpoint
ALTER TABLE "settings" ADD CONSTRAINT "settings_finance_step_check" CHECK (key <> 'finance_step' OR (jsonb_typeof(value) = 'boolean'));--> statement-breakpoint
-- 06 Finance step switched off 2: "no money action has a row on it" (plan of 4.10c, decided item 7,
-- Look first). Checked on the row's insert only: rows are never updated, and the mark is written
-- once, by the Principal's approval, before any money row can exist on the order (money rows are
-- written only on Open and Waiting for settlement orders). An unknown order is left to its
-- foreign key.
CREATE FUNCTION "money_rows_not_skipped"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
	IF EXISTS (SELECT 1 FROM "orders" WHERE "id" = NEW."order_id" AND "skipped_finance") THEN
		RAISE EXCEPTION 'An order that skipped Finance has no money rows.'
			USING ERRCODE = 'check_violation',
				CONSTRAINT = 'money_rows_not_skipped',
				TABLE = TG_TABLE_NAME;
	END IF;
	RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "money_rows_not_skipped"
	BEFORE INSERT ON "money_rows"
	FOR EACH ROW EXECUTE FUNCTION "money_rows_not_skipped"();
